#!/usr/bin/env node
// Dumps a protobuf message family from a Cursor webpack bundle by loading the bundle and
// reading protobuf-es runtime reflection. Newer Cursor bundles declare schemas in a compact
// `static $(){return["Name|1 field 9|..."]}` form that the Go extractor does not parse.
//
// usage: node dump-runtime-protos.cjs <bundle.js> <out.proto> <package> <RootMessage>...
// example:
//   node dump-runtime-protos.cjs \
//     "$LOCALAPPDATA/Programs/cursor/resources/app/extensions/cursor-agent-host/dist/main.js" \
//     protocols/cursor/aiserver_run_inference_v1.proto aiserver.v1 \
//     RunInferenceClientMessage RunInferenceServerMessage
"use strict";
const fs = require("fs");
const Module = require("module");
const path = require("path");

const [bundle, out, pkg, ...roots] = process.argv.slice(2);
if (!bundle || !out || !pkg || roots.length === 0) {
  console.error("usage: dump-runtime-protos.cjs <bundle.js> <out.proto> <package> <RootMessage>...");
  process.exit(2);
}

// Extension bundles import `vscode` at load time; a permissive stub lets modules evaluate.
function stub() {
  const proxy = new Proxy(function () {}, {
    get: (_, key) => (key === Symbol.toPrimitive ? () => "" : key === "then" ? undefined : proxy),
    apply: () => proxy,
    construct: () => proxy,
  });
  return proxy;
}
const load = Module._load;
Module._load = function (request, parent, isMain) {
  return request === "vscode" ? stub() : load.call(this, request, parent, isMain);
};

const runtime = "function __webpack_require__(e){";
let source = fs.readFileSync(bundle, "utf8");
if (!source.includes(runtime)) throw new Error(`webpack runtime not found in ${bundle}`);
source = source.replace(runtime, `globalThis.__cursorRequire=__webpack_require__;${runtime}`);
const host = new Module(bundle, null);
host.filename = bundle;
host.paths = Module._nodeModulePaths(path.dirname(bundle));
try {
  host._compile(source, bundle);
} catch (error) {
  console.error(`bundle entry threw (ignored): ${String(error).slice(0, 160)}`);
}
const req = globalThis.__cursorRequire;
if (!req) throw new Error("webpack require was not captured");

const types = new Map();
for (const id of Object.keys(req.m)) {
  const text = req.m[id].toString();
  if (!roots.some((name) => text.includes(`"${name}|`) || text.includes(`"${pkg}.${name}"`))) continue;
  let exports;
  try {
    exports = req(id);
  } catch (error) {
    console.error(`module ${id} threw (skipped): ${String(error).slice(0, 160)}`);
    continue;
  }
  for (const value of Object.values(exports)) {
    if (typeof value === "function" && typeof value.typeName === "string") types.set(value.typeName, value);
  }
}

const messages = new Map();
const enums = new Map();
const external = new Set();
const queue = roots.map((name) => {
  const type = types.get(`${pkg}.${name}`);
  if (!type) throw new Error(`root ${pkg}.${name} not found`);
  return type;
});
const own = (typeName) => {
  if (!typeName.startsWith(`${pkg}.`)) return false;
  if (typeName.slice(pkg.length + 1).includes(".")) throw new Error(`nested type not supported: ${typeName}`);
  return true;
};
while (queue.length) {
  const type = queue.shift();
  if (messages.has(type.typeName)) continue;
  messages.set(type.typeName, type);
  for (const field of type.fields.list()) {
    for (const ref of [field.T, field.V?.T]) {
      if (!ref || typeof ref !== "object" && typeof ref !== "function") continue;
      if (!ref.typeName) continue;
      if (!own(ref.typeName)) external.add(ref.typeName);
      else if (typeof ref === "function") queue.push(ref);
      else enums.set(ref.typeName, ref);
    }
  }
}

const SCALARS = { 1: "double", 2: "float", 3: "int64", 4: "uint64", 5: "int32", 6: "fixed64", 7: "fixed32", 8: "bool", 9: "string", 12: "bytes", 13: "uint32", 15: "sfixed32", 16: "sfixed64", 17: "sint32", 18: "sint64" };
const GOOGLE = { Struct: "struct", Value: "struct", ListValue: "struct", NullValue: "struct", Empty: "empty", Timestamp: "timestamp", Duration: "duration" };
function importFor(typeName) {
  if (typeName.startsWith("google.protobuf.")) {
    const file = GOOGLE[typeName.split(".").pop()];
    if (!file) throw new Error(`no import known for ${typeName}`);
    return `google/protobuf/${file}.proto`;
  }
  return `${typeName.split(".").slice(0, -1).join("_")}.proto`;
}
function name(typeName) {
  return own(typeName) ? typeName.slice(pkg.length + 1) : `.${typeName}`;
}
function fieldType(kind, T) {
  return kind === "scalar" ? SCALARS[T] ?? (() => { throw new Error(`scalar ${T}`); })() : name(T.typeName);
}

const product = path.join(path.dirname(bundle), "..", "..", "..", "product.json");
const version = fs.existsSync(product) ? JSON.parse(fs.readFileSync(product, "utf8")).version : "unknown";
const lines = [
  `// Generated by support/cursor-protocol-extractor/scripts/dump-runtime-protos.cjs`,
  `// from Cursor ${version} (${path.basename(path.dirname(path.dirname(bundle)))}). Do not edit by hand.`,
  `// Roots: ${roots.join(", ")}`,
  'syntax = "proto3";',
  "",
  `package ${pkg};`,
  "",
  ...[...new Set([...external].map(importFor))].sort().map((file) => `import "${file}";`),
  "",
];
for (const [typeName, type] of [...messages].sort()) {
  lines.push(`message ${name(typeName)} {`);
  const oneofs = new Map();
  for (const field of type.fields.list()) {
    let decl;
    if (field.kind === "map") {
      decl = `map<${SCALARS[field.K]}, ${fieldType(field.V.kind, field.V.T)}> ${field.name} = ${field.no};`;
    } else {
      const label = field.oneof ? "" : field.repeated ? "repeated " : field.opt ? "optional " : "";
      decl = `${label}${fieldType(field.kind, field.T)} ${field.name} = ${field.no};`;
    }
    if (field.oneof) {
      if (!oneofs.has(field.oneof.name)) oneofs.set(field.oneof.name, []);
      oneofs.get(field.oneof.name).push(decl);
    } else {
      lines.push(`  ${decl}`);
    }
  }
  for (const [oneof, decls] of oneofs) lines.push(`  oneof ${oneof} {`, ...decls.map((d) => `    ${d}`), "  }");
  lines.push("}", "");
}
for (const [typeName, type] of [...enums].sort()) {
  lines.push(`enum ${name(typeName)} {`, ...type.values.map((v) => `  ${v.name} = ${v.no};`), "}", "");
}
fs.writeFileSync(out, lines.join("\n"));
console.log(`wrote ${messages.size} messages and ${enums.size} enums (${external.size} external refs) to ${out}`);
